  back_lowbar:{knee:[85,110],hip:[60,90],trunk:[40,60],ankle:[70,85],descent:[2,3],ascent:[1,2]},
  front:{knee:[75,95],hip:[75,105],trunk:[15,35],ankle:[65,80],descent:[2,3],ascent:[1,2]},
