// BODY_ADJ  [const]  index.html:2673-2675
// sha256 988b98ca2ae408a2790621eb2796625574d575fdd53c23a2d55443c29af1c312
// --------------------------------------------------------------------------
const BODY_ADJ={
  long_femur:{trunk:[5,10],hip:[-5,-5]}, balanced:{trunk:[0,0],hip:[0,0]}, short_femur:{trunk:[-5,-5],hip:[5,5]},
};

// --------------------------------------------------------------------------
// getStd  [function]  index.html:2676-2680
// sha256 1fb79520cf1d47f60926514eec67964d0a5dcf0f16f3ba5ce2fadf6edeaf9f8c
// --------------------------------------------------------------------------
function getStd(){
  const p=APP.profile||{};const base={...STANDARDS[p.squatType||'bodyweight']};
  const adj=BODY_ADJ[p.bodyType||'balanced']||BODY_ADJ.balanced;
  return{knee:[...base.knee],hip:[base.hip[0]+adj.hip[0],base.hip[1]+adj.hip[1]],trunk:[base.trunk[0]+adj.trunk[0],base.trunk[1]+adj.trunk[1]],ankle:[...base.ankle],descent:[...base.descent],ascent:[...base.ascent]};
}

// --------------------------------------------------------------------------
// getACSM  [function]  index.html:2682-2682
// sha256 ae19ec7453ae9c556a7869cb53f6d831267e3ed614940f5b2fd742ede21e62ab
// --------------------------------------------------------------------------
function getACSM(){const s=getStd();return{knee:{min:s.knee[0],max:s.knee[1]},hip:{min:s.hip[0],max:s.hip[1]},trunk:{min:s.trunk[0],max:s.trunk[1]},ankle:{min:s.ankle[0],max:s.ankle[1]}};}

