// sha256 11eef8c772b90d6aa06c7de30c88231634d9285fa681e06c961753d97e961620
// --------------------------------------------------------------------------
function dev(v,r){if(v<r.min)return v-r.min;if(v>r.max)return v-r.max;return 0;}

// --------------------------------------------------------------------------
// onPoseResults  [function]  index.html:3308-3369
// sha256 768899d2914f608b1ca2cd8b7e04eba645b554d804be3b155b54b86e9818f2a2
// --------------------------------------------------------------------------
function onPoseResults(results,canvas,ctx){
  canvas.width=canvas.clientWidth;canvas.height=canvas.clientHeight;ctx.clearRect(0,0,canvas.width,canvas.height);
  // ── ver2: heartbeat — record last successful pose detection
  APP._lastPoseAt=Date.now();
  APP._autoRecoverCount=0;APP._recoveryGaveUp=false;   // ver7-D7.65: 결과 콜백 도착 = 파이프라인 생존 → 복구 카운터·포기상태 리셋
  if(APP._poseHeartbeatEl){APP._poseHeartbeatEl.textContent='● 감지 OK';APP._poseHeartbeatEl.style.color='#2ecc71';}
  if(!results.poseLandmarks){
    if(APP._poseHeartbeatEl){APP._poseHeartbeatEl.textContent='○ 감지 대기';APP._poseHeartbeatEl.style.color='#f1c40f';}
    return;
  }
  const lm=results.poseLandmarks;APP.landmarks=lm;
  drawPose(ctx,lm,canvas.width,canvas.height);
  if(!APP.isAnalyzing)return;

  // Pick visible side
  const lVis=(lm[11].visibility+lm[23].visibility+lm[25].visibility+lm[27].visibility)/4;
  const rVis=(lm[12].visibility+lm[24].visibility+lm[26].visibility+lm[28].visibility)/4;
  let shoulder,hip,knee,ankle,foot;
  if(lVis>rVis){shoulder=lm[11];hip=lm[23];knee=lm[25];ankle=lm[27];foot=lm[31];}
  else{shoulder=lm[12];hip=lm[24];knee=lm[26];ankle=lm[28];foot=lm[32];}

  APP._lastLandmarkCoords={hip:{x:hip.x,y:hip.y},knee:{x:knee.x,y:knee.y},ankle:{x:ankle.x,y:ankle.y},shoulder:{x:shoulder.x,y:shoulder.y}};

  // ver7-D7.67 — 종횡비 보정 (E1 Tier 2 가 발견한 최대 오차원)
  // MediaPipe 정규화 좌표는 x 를 프레임 폭으로, y 를 높이로 나눈 값이다. 폭≠높이면
  // 이는 비등방 스케일링이고, 비등방 스케일링은 각도를 보존하지 않는다. D7.66 까지
  // 앱은 이 좌표로 곧장 각도를 계산해, 실제 이미지 평면 대비 무릎 -32.7° 편향이 있었다.
  // x 에 (W/H) 를 곱하면 두 축이 모두 '프레임 높이' 단위가 되어 등방이 된다.
  // 측정 근거: E1 Tier 2 191 반복 — 무릎 MAE 32.73°→15.11°, 몸통 13.03°→6.49°,
  // 점수 AUC 0.627→0.710. (E1_benchmark/results/aspect_experiment.json)
  const _vEl=document.getElementById('webcam');
  const _vw=(_vEl&&_vEl.videoWidth)||(results.image&&results.image.width)||0;
  const _vh=(_vEl&&_vEl.videoHeight)||(results.image&&results.image.height)||0;
  const AR=(_vw>0&&_vh>0)?_vw/_vh:1;   // 프레임 기하를 못 읽으면 보정하지 않는다
  APP._frameAR=AR;
  const iso=p=>({x:p.x*AR,y:p.y,z:p.z,visibility:p.visibility});

  const ka=smooth('knee',calcAngle(iso(hip),iso(knee),iso(ankle)));
  const ha=smooth('hip',calcAngle(iso(shoulder),iso(hip),iso(knee)));
  const ta=smooth('trunk',calcTrunk(iso(shoulder),iso(hip)));
  const aa=smooth('ankle',calcAngle(iso(knee),iso(ankle),iso(foot)));
  const ACSM=getACSM();

  updateBar('knee',ka,ACSM.knee);updateBar('hip',ha,ACSM.hip);updateBar('trunk',ta,ACSM.trunk);updateBar('ankle',aa,ACSM.ankle);
  // Angle text overlay on video (ver6.1: mirror-corrected for selfie-flipped canvas)
  const txt=`${t('exercise.knee')}: ${ka.toFixed(0)}°  ${t('exercise.trunk')}: ${ta.toFixed(0)}°`;
  drawMirroredText(ctx,txt,10,30,{font:'bold 16px sans-serif',strokeStyle:'#000',lineWidth:3,fillStyle:'#f1c40f'});

  // ver7-D7.71: 정렬 지표는 보정 이전의 원 좌표에서 계산한다 — 좌우 분리 폭 자체가
  // 신호이므로 등방 변환을 적용하면 두 축의 상대 관계가 바뀐다.
  const _open=kqViewOpenness(lm,AR);
  if(_open!==null){
    APP._viewOpen=_open;
    APP._viewSamples=APP._viewSamples||[];
    APP._viewSamples.push(_open);
    if(APP._viewSamples.length>900)APP._viewSamples.shift();   // 최근 30초만 유지
  }
  updateViewGuide(_open);

  detectPhase(ka,ha,ta,aa,canvas);
  updateLiveFeedback(ka,ha,ta,aa);
}

// --------------------------------------------------------------------------
// calcAngle  [function]  index.html:3117-3117
// sha256 6f2cdfefef004f56e56692ca4537051b48d71cc123e96fd4f46c05a03517ea48
// --------------------------------------------------------------------------
function calcAngle(a,b,c){const ba={x:a.x-b.x,y:a.y-b.y},bc={x:c.x-b.x,y:c.y-b.y};const dot=ba.x*bc.x+ba.y*bc.y,mag=Math.sqrt(ba.x*ba.x+ba.y*ba.y)*Math.sqrt(bc.x*bc.x+bc.y*bc.y);if(!mag)return 0;return Math.acos(Math.min(1,Math.max(-1,dot/mag)))*(180/Math.PI);}

// --------------------------------------------------------------------------
// calcTrunk  [function]  index.html:3134-3134
// sha256 eaa4d695ea06041adf665511fda7c1740e79fb5b709fc3af9fcb646999f5475c
// --------------------------------------------------------------------------
function calcTrunk(s,h){return Math.atan2(Math.abs(s.x-h.x),Math.abs(s.y-h.y))*(180/Math.PI);}

// --------------------------------------------------------------------------
// calcAsymmetry  [function]  index.html:3275-3305
// sha256 2dc5529a4333c092e0e1c0ea03fbd89513a040a1c1ad6e1310cd8d13fe34da75
// --------------------------------------------------------------------------
function calcAsymmetry(landmarks){
  const vis=0.5;
  // ver7-D7.67: 좌우 비대칭도 각도 기반이므로 onPoseResults 와 동일하게 등방 좌표에서 계산한다.
  // 보정 전에는 왜곡된 각도끼리 비교해 비대칭 위험도(>10°=high)가 잘못 판정될 수 있었다.
  const _ar=(typeof APP!=='undefined'&&APP._frameAR)||1;
  landmarks=landmarks.map(p=>p?{x:p.x*_ar,y:p.y,z:p.z,visibility:p.visibility}:p);
  const left={},right={};
  if(landmarks[23]?.visibility>vis&&landmarks[25]?.visibility>vis&&landmarks[27]?.visibility>vis){
    left.knee=calcAngle(landmarks[23],landmarks[25],landmarks[27]);
    left.hip=calcAngle(landmarks[11],landmarks[23],landmarks[25]);
    left.ankle=calcAngle(landmarks[25],landmarks[27],landmarks[31]);
  }
  if(landmarks[24]?.visibility>vis&&landmarks[26]?.visibility>vis&&landmarks[28]?.visibility>vis){
    right.knee=calcAngle(landmarks[24],landmarks[26],landmarks[28]);
    right.hip=calcAngle(landmarks[12],landmarks[24],landmarks[26]);
    right.ankle=calcAngle(landmarks[26],landmarks[28],landmarks[32]);
  }
  const asym={};
  ['knee','hip','ankle'].forEach(joint=>{
    if(left[joint]&&right[joint]){
      asym[joint]={
        left:Math.round(left[joint]*10)/10,
        right:Math.round(right[joint]*10)/10,
        diff:Math.round(Math.abs(left[joint]-right[joint])*10)/10,
        side:left[joint]>right[joint]?'L':'R',
        risk:Math.abs(left[joint]-right[joint])>10?'high':Math.abs(left[joint]-right[joint])>5?'moderate':'normal'
      };
    }
  });
  return asym;
}

// --------------------------------------------------------------------------
// kqViewOpenness  [function]  index.html:3146-3161
// sha256 c3040165c4d25d3de55bfb36b436eb16197953c2d054ab96d7d671a674ec6edf
// --------------------------------------------------------------------------
function kqViewOpenness(lm,ar){
  if(!lm||!lm[11]||!lm[12]||!lm[23]||!lm[24])return null;
  // ver7-D7.72: 반드시 등방(종횡비 보정) 좌표에서 계산한다.
  // 이 지표는 'x 방향 거리 / y 방향 거리' 의 비이고, 비등방 정규화 좌표에서 그 비는
  // 프레임 형상에 비례해 달라진다(정확히 H/W 배). D7.71 은 보정 전 좌표를 썼는데,
  // 그 결과 동일한 정면 자세가 9:16 에서 0.978, 4:3 에서 0.413 로 읽혔다.
  // 임계값을 9:16 코퍼스에서 골랐으므로 4:3 프로덕션에서는 완전한 정면조차
  // 'fair' 로 분류되어 경고가 발화하지 않았다. yaw 스윕이 이 결함을 드러냈다.
  const AR=(typeof ar==='number'&&ar>0)?ar
          :((typeof APP!=='undefined'&&APP._frameAR>0)?APP._frameAR:1);
  const midShY=(lm[11].y+lm[12].y)/2, midHipY=(lm[23].y+lm[24].y)/2;
  const torso=Math.abs(midHipY-midShY);
  if(!(torso>1e-4))return null;                       // 몸통이 안 잡히면 판정 보류
  const shW=Math.abs(lm[11].x-lm[12].x)*AR, hipW=Math.abs(lm[23].x-lm[24].x)*AR;
  return (shW+hipW)/(2*torso);
}

