const KQ_VIEW_WARN=0.13;

// --------------------------------------------------------------------------
// kqViewGrade  [function]  index.html:3268-3273
// sha256 0d23ad571457debc245d44a93ec6e025db2f3cce2e51ce8d7066b82e9c2d9836
// --------------------------------------------------------------------------
function kqViewGrade(o){
  if(o===null||o===undefined)return {k:'unknown',label:'정렬 확인 중',cls:'fb-good'};
  if(o<=KQ_VIEW_GOOD)return {k:'good',label:'측면 정렬 좋음',cls:'fb-good'};
  if(o<=KQ_VIEW_WARN)return {k:'fair',label:'약간 틀어짐 — 몸을 조금 더 옆으로',cls:'fb-warn'};
  return {k:'poor',label:'정면에 가깝습니다 — 카메라를 옆에서 보도록 서주세요',cls:'fb-bad'};
}

