function smooth(k,v,a=0.3){APP.smoothAngles[k]=APP.smoothAngles[k]*(1-a)+v*a;return APP.smoothAngles[k];}

// --------------------------------------------------------------------------
// detectPhase  [function]  index.html:3380-3478
// sha256 64a06d344ab463bf2a2b449c512e143bfb31d0a6c85e9df0a5e77f394817a7c4
// PATCHED: __E1_TH threshold hook — sha256 은 패치 전 원문 기준. 전문은 provenance.patches 참조
// --------------------------------------------------------------------------
function detectPhase(knee,hip,trunk,ankle,canvas){
  const now=Date.now(),ACSM=getACSM();
  // ver2: thresholds widened so partial squats register reliably
  // STAND raised slightly; BOTTOM_TH capped at 120° so any squat to ~115-120° counts as bottom
  // ver7-D7.67: 종횡비 보정으로 최저점 각도가 더 높게(덜 굴곡으로) 읽히므로 깊이 게이트를
  // 보정된 공간에서 재도출했다. 그대로 두면 얕은 반복이 게이트를 못 넘어 재현율이
  // 0.901→0.791 로 떨어진다. +15→+35 는 보정이 최저점을 올린 폭(약 20~25°)을 상쇄한다.
  // dev 녹화에서 선택하고 held-out test 에서 검증 (recall -0.012, precision +0.011).
  // 이 임계는 '탐지 게이트'이지 품질 기준이 아니다 — 깊이의 적정성은 repScore() 가
  // STANDARDS(ACSM/NASM)로 따로 채점한다.
  const __TH=(typeof globalThis!=='undefined'&&globalThis.__E1_TH)||null;const STAND=__TH?__TH.stand:160,BOTTOM_TH=__TH?__TH.bottom:Math.min(ACSM.knee.max+35,145),PARALLEL_TH=__TH?__TH.parallel:150;
  // ver7-D7.66 — 카운팅 결함 수정: 반복 완료 임계를 피험자의 실제 기립 신전각에 맞춘다.
  // 기존에는 무조건 160° 복귀를 요구했고, 정점에서 무릎을 완전히 펴지 않는
  // 연속긴장(constant-tension) 수행자는 반복이 아예 카운팅되지 않았다.
  // (E1 Tier 1.5 / REHAB24-6: 191회 중 18회 미검출, 특정 피험자는 30% 이상)
  // 완전 신전 사용자에게는 종전과 동일하게 160°가 적용된다(140° 하한 가드).
  const REP_TOP=Math.max(140,Math.min(STAND,(APP._repTopKnee||STAND)-5));
  const pushAngles=()=>{APP.currentRepAngles.knee.push(knee);APP.currentRepAngles.hip.push(hip);APP.currentRepAngles.ankle.push(ankle);APP.currentRepAngles.trunk.push(trunk);};
  // ver7-D7.66 — 템포 결함 수정: 실제 최저점 시각을 추적해 하강/상승 구간의 경계로 삼는다.
  const trackBottom=()=>{if(knee<APP._repMinKnee){APP._repMinKnee=knee;APP._repMinKneeAt=now;}};

  switch(APP.sqPhase){
    case 'stand':
      // ver7-D7.66: 이 사람이 실제로 도달하는 기립 신전각과, 기립을 벗어난 시각을 추적
      if(knee>APP._standPeakKnee)APP._standPeakKnee=knee;
      // 하강이 시작되지 않은 동안에는 개시 시각을 계속 현재로 밀어 둔다. '정점 근처'로
      // 판정하면 정점보다 낮은 자세로 오래 서 있을 때 개시 시각이 낡아 하강 시간이
      // 수십 초로 부풀었다(E1 Tier 1.5에서 최대 22.5초 관측).
      if(knee>=APP.prevKneeAngle-0.5)APP._standAt=now;
      // Capture standing pose (once per rep, right before descent starts)
      if(knee>=STAND&&!APP.standingCaptured&&APP._lastLandmarkCoords){
        APP.currentPhaseCapture.standing=capturePhasePhoto(knee,hip,trunk,ankle);
        APP.standingCaptured=true;
      }
      if(knee<STAND-15){
        APP.sqPhase='descending';
        // ver7-D7.66: 임계 교차(145°)가 아니라 기립을 벗어난 실제 시점을 하강 개시로 기록.
        // 기존은 145°->115° 구간 통과 시간을 '하강 시간'으로 보고해 실제의 약 24%만 측정했다.
        APP.descentStart=APP._standAt||now;
        APP._repTopKnee=APP._standPeakKnee||STAND;
        APP._repMinKnee=knee;APP._repMinKneeAt=now;APP._ascentPeak=0;
        APP.currentRepAngles={knee:[],hip:[],ankle:[],trunk:[]};
        APP.bottomReached=false;APP.currentBottomCoords=null;
        APP.parallelCaptured=false;
        updatePI('pi-down',t('exercise.descending'));
      }break;
    case 'descending':
      pushAngles();trackBottom();
      // Capture parallel position (~110-120°)
      if(!APP.parallelCaptured&&knee<=PARALLEL_TH&&knee>BOTTOM_TH){
        APP.currentPhaseCapture.parallel=capturePhasePhoto(knee,hip,trunk,ankle);
        APP.parallelCaptured=true;
      }
      if(knee<BOTTOM_TH){
        APP.sqPhase='bottom';APP.bottomTimestamp=now;APP.bottomReached=true;
        APP.currentBottomCoords=APP._lastLandmarkCoords;
        captureSnapshot(canvas,knee,hip,trunk,ankle);
        // Capture bottom phase photo
        APP.currentPhaseCapture.bottom=capturePhasePhoto(knee,hip,trunk,ankle);
        updatePI('pi-bottom',t('exercise.bottom'));speak(t('exercise.goUp'));
      }
      if(knee>REP_TOP){APP.sqPhase='stand';APP._standPeakKnee=knee;updatePI('pi-stand',t('exercise.standing'));}break;
    case 'bottom':
      pushAngles();trackBottom();
      if(knee>BOTTOM_TH+15&&knee>APP.prevKneeAngle){APP.sqPhase='ascending';APP.ascentStart=now;updatePI('pi-up',t('exercise.ascending'));}break;
    case 'ascending':
      pushAngles();trackBottom();
      if(knee>APP._ascentPeak)APP._ascentPeak=knee;
      // ver7-D7.66 — 카운팅 결함 수정 (2): 반복의 끝은 '절대 각도 복귀'가 아니라 '동작의 정점'이다.
      // 정점에서 완전히 펴지 않는 연속 수행 시 FSM 이 bottom<->ascending 만 오가며 여러 반복이
      // 하나로 병합됐다 (E1: PM_126 은 5회 연속 수행이 1회로 카운트됨).
      // 정점을 찍고 다시 내려가기 시작하면 = 다음 반복의 시작 → 현재 반복을 완료 처리한다.
      // ver7-D7.67: 이 가드는 '정점 부근까지 올라왔는가'를 묻는 것이므로 깊이 게이트가 아니라
      // STAND 를 기준으로 삼는다. D7.66 에서는 BOTTOM_TH+25 로 묶여 있었는데, D7.67 이
      // 게이트를 135 로 올리자 이 값이 160(=STAND)이 되어 되돌림 판정이 영영 발화하지 못했고
      // D7.66 의 카운팅 수정이 통째로 무력화됐다 (Tier 1.5 재현율 0.984→0.916 으로 발견).
      const _topOut=(APP._ascentPeak>=STAND-20&&knee<APP._ascentPeak-6);
      if(knee>=REP_TOP||_topOut){
        // ver7-D7.66: 하강 = 기립 이탈 -> 최저점, 상승 = 최저점 -> 복귀.
        // 기존은 중간 각도 구간의 통과 시간이어서 정상 템포(1~4초)가 전부
        // repScore 최대 감점 구간(<1초)에 포화되어 템포 항목의 변별력이 0이었다.
        const dt=(APP._repMinKneeAt-APP.descentStart)/1000,at=(now-APP._repMinKneeAt)/1000;
        APP.lastRepTiming={descentTime:dt,ascentTime:at};
        if(APP.bottomReached){
          // Save 3-phase capture for this rep
          APP.phaseCaptures.push({...APP.currentPhaseCapture,rep:APP.repCount+1});
          completeRep(knee,hip,trunk,ankle,dt,at);
        }
        // Reset for next rep
        APP.currentPhaseCapture={standing:null,parallel:null,bottom:null};
        APP.standingCaptured=false;APP.parallelCaptured=false;
        APP.sqPhase='stand';APP._standPeakKnee=_topOut?APP._ascentPeak:knee;
        APP._ascentPeak=0;
        updatePI('pi-stand',`${APP.repCount}/${APP.repTarget} 완료!`);
      }
      if(knee<BOTTOM_TH){APP.sqPhase='bottom';APP.bottomTimestamp=Date.now();updatePI('pi-bottom','최저점');}break;
  }
  APP.prevKneeAngle=knee;
}

// --------------------------------------------------------------------------
// completeRep  [function]  index.html:3568-3585
// sha256 87bc413c278ff6b9d0689b294df2c3ad7e63b6dd212db550cab562051a6e57f8
// --------------------------------------------------------------------------
function completeRep(knee,hip,trunk,ankle,dt,at){
  APP.repCount++;
  const snap=APP.repSnapshots[APP.repSnapshots.length-1];
  const ba=snap?snap.angles:{knee,hip,trunk,ankle};
  // Use min/max from accumulated angles if available
  const rk=APP.currentRepAngles.knee.length?Math.min(...APP.currentRepAngles.knee):ba.knee;
  const rh=APP.currentRepAngles.hip.length?Math.min(...APP.currentRepAngles.hip):ba.hip;
  const rt=APP.currentRepAngles.trunk.length?Math.max(...APP.currentRepAngles.trunk):ba.trunk;
  const ra=APP.currentRepAngles.ankle.length?Math.min(...APP.currentRepAngles.ankle):ba.ankle;

  const _repAsym=APP.landmarks?calcAsymmetry(APP.landmarks):{};
  APP.reps.push({rep:APP.repCount,knee:rk,hip:rh,trunk:rt,ankle:ra,descentTime:Math.max(.3,dt),ascentTime:Math.max(.3,at),timestamp:Date.now(),bottomCoords:APP.currentBottomCoords,asym:Object.keys(_repAsym).length?_repAsym:null});
  document.getElementById('repCount').textContent=APP.repCount;
  document.getElementById('eccentricTime').textContent=dt.toFixed(1);
  document.getElementById('concentricTime').textContent=at.toFixed(1);
  showRepPopup(APP.repCount);speak(APP.repCount+t('exercise.rep'));
  if(APP.repCount>=APP.repTarget)setTimeout(()=>finishExercise(),1500);
}

// --------------------------------------------------------------------------
// repScore  [function]  index.html:3775-3784
// sha256 357dfb0cecb8ca192d63ff8b95e27157e0d9c3bcd6039f0c24f7d38cb3e1b22e
// --------------------------------------------------------------------------
function repScore(r){
  const ACSM=getACSM(),mp=50;
  const kp=Math.min(mp,Math.abs(dev(r.knee,ACSM.knee))*2.5);
  const tp=Math.min(mp,Math.abs(dev(r.trunk,ACSM.trunk))*2.5);
  const hp=Math.min(mp,Math.abs(dev(r.hip,ACSM.hip))*2);
  const ap=Math.min(mp,Math.abs(dev(r.ankle,ACSM.ankle))*2);
  let dp=0;if(r.descentTime!=null){if(r.descentTime<1)dp=40;else if(r.descentTime<2)dp=(2-r.descentTime)*30;else if(r.descentTime>4)dp=Math.min(30,(r.descentTime-3)*10);else if(r.descentTime>3)dp=(r.descentTime-3)*10;}
  let atp=0;if(r.ascentTime!=null){if(r.ascentTime<.5)atp=30;else if(r.ascentTime<1)atp=(1-r.ascentTime)*30;else if(r.ascentTime>3)atp=Math.min(30,(r.ascentTime-2)*10);else if(r.ascentTime>2)atp=(r.ascentTime-2)*10;}
  return Math.max(0,Math.round(100-(kp*.30+tp*.25+hp*.20+ap*.10+dp*.10+atp*.05)));
}

